-- CA_0329_torrance_council_districts.sql
--
-- Torrance (LA County, place 0680000) — give the six council seats their districts.
-- Follow-up to CA_0324 (#1090), which fixed WHO sits but left the seats "At-Large".
--
-- ── WHAT IS WRONG ────────────────────────────────────────────────────────────────────────
--
-- Torrance has elected its council by district since an ordinance of 2018-06-19 (city page,
-- "List of Districts"): six districts, each with one member, plus a Mayor elected citywide.
-- We modelled it as six "At-Large" council offices, each on its own district row pointing at
-- the whole city (TIGER place 0680000). So every Torrance address was shown all six council
-- members as its representatives, instead of the one for its district.
--
-- ── SOURCE ──────────────────────────────────────────────────────────────────────────────
--
--   G1  City of Torrance, Community Development Dept., GIS and Mapping Group: "Torrance City
--       Council Districts", Council_Districts FeatureServer layer 4, read 2026-10-26:
--       https://services1.arcgis.com/38fAqAZVRCrVtPUU/arcgis/rest/services/Council_Districts/FeatureServer/4
--       This is the layer behind the city's own "Electoral Districts Lookup" app, linked from
--       https://www.torranceca.gov/Government/Council-Districts/Districts . Service last edited
--       2026-09-23. Its CurrentOfficial field names Kartsonis (1), Lewis (2), Sheikh (3),
--       Barnett (4), Lieu (5), Gerson (6) — the same six CA_0324 seated, so roster and map agree.
--
-- ── HOW IT WAS CHECKED (2026-10-26) ──────────────────────────────────────────────────────
--
--   * Against the county's ballot-building data: all 569 LA County Registrar-Recorder precincts
--     in Torrance (Political_Boundaries MapServer 34, DST_CITY='TR', DIV_CITY 1-6) fall inside
--     the city polygon with the SAME district number — 569 of 569. Dissolved by DIV_CITY, the
--     precincts match G1 at IoU 0.993-0.999 per district. So the city's map is the one the
--     county builds Torrance ballots from.
--   * The six polygons do not overlap, and 99.93% of their area lies inside the TIGER place.
--   * They cover 83% of the TIGER place. The other 10.5 km2 is one piece west of -118.3746 —
--     the Pacific Ocean, which TIGER's place outline includes and a council map does not. No
--     address sits there.
--
-- ── WHAT THIS DOES ──────────────────────────────────────────────────────────────────────
--
--   1. Loads the six polygons (X0001, the LA County cities' council-district code; geo_id and
--      ocd_id 'torrance-council-district-N' so check:district-vintage can gate them).
--   2. Repoints each council office's own district row onto its polygon. Which row is which
--      district is fixed by the member who holds it (G1 CurrentOfficial = our current holder).
--      The rows' city-level population/census unit are cleared: they described the whole city.
--   3. Retitles the six offices "Council Member (District N)" (the Downey CA_0307 shape).
--   The Mayor stays on the whole-city row: the Mayor is elected citywide.
--
-- IDEMPOTENT: polygons NOT EXISTS-guarded; repoints and retitles are plain assignments.

BEGIN;

-- ─── 0. PRE-FLIGHT: each district row holds exactly the office and member we think ─────────
DO $$
DECLARE v_txt text;
BEGIN
  SELECT string_agg(v.n || ':' || coalesce(p.full_name, 'NOBODY'), ', ') INTO v_txt
    FROM (VALUES
      (1, '302ce5a0-7d1c-47f5-9d38-4029c04e902e'::uuid, '8391fb00-171a-4984-8bc7-2d080fc03a24'::uuid, 'David Kartsonis'),
      (2, '738b8cd8-5fe8-442b-8371-74f6781072aa'::uuid, '95879f8c-5cd2-4042-86eb-b11c14fea767'::uuid, 'Bridgett Lewis'),
      (3, 'f0344be1-8f0a-4244-9fa3-05119d11f584'::uuid, '0542b22b-61e1-4a3d-be3c-104a33252d21'::uuid, 'Asam Sheikh'),
      (4, '91e386c4-4562-4a56-bc36-cf3e15cbf581'::uuid, '143f683f-96a8-4924-92fa-fbc6bc3444e9'::uuid, 'Linda Barnett'),
      (5, '84e45ab7-b30f-44ad-b379-b83dc6cedb8f'::uuid, '220e2cb5-f268-423a-b9a8-2f187f94d9b5'::uuid, 'Betty Lieu'),
      (6, '95177e7e-78e2-4139-a82b-9469bbcb7965'::uuid, '7f596dd4-1480-408f-bef8-b7b951b57142'::uuid, 'Jeremy Gerson')
    ) AS v(n, district_row, office_id, expected)
    LEFT JOIN essentials.offices o ON o.id = v.office_id AND o.district_id = v.district_row
    LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
    LEFT JOIN essentials.politicians p ON p.id = och.politician_id
   WHERE p.full_name IS DISTINCT FROM v.expected
      OR (SELECT count(*) FROM essentials.offices o2 WHERE o2.district_id = v.district_row) <> 1;
  IF v_txt IS NOT NULL THEN
    RAISE EXCEPTION 'CA_0329: Torrance district rows are not as expected (district:holder): %', v_txt;
  END IF;
END $$;

