  ) AS v(geo_id, name, gj)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.geofence_boundaries b WHERE b.geo_id = v.geo_id AND b.mtfcc = 'X0001');

-- ─── 2. Repoint each council office's district row onto its polygon ─────────────────────────
UPDATE essentials.districts d
   SET geo_id = 'torrance-council-district-' || v.n,
       mtfcc = 'X0001',
       label = 'District ' || v.n,
       district_id = v.n::text,
       ocd_id = 'ocd-division/country:us/state:ca/place:torrance/ward:' || v.n,
       official_web_url = 'https://www.torranceca.gov/Government/Council-Districts/Districts/District-' || v.n,
       population = NULL, population_source_year = NULL, census_unit_id = NULL
  FROM (VALUES
    ('302ce5a0-7d1c-47f5-9d38-4029c04e902e'::uuid, 1),
    ('738b8cd8-5fe8-442b-8371-74f6781072aa'::uuid, 2),
    ('f0344be1-8f0a-4244-9fa3-05119d11f584'::uuid, 3),
    ('91e386c4-4562-4a56-bc36-cf3e15cbf581'::uuid, 4),
    ('84e45ab7-b30f-44ad-b379-b83dc6cedb8f'::uuid, 5),
    ('95177e7e-78e2-4139-a82b-9469bbcb7965'::uuid, 6)
  ) AS v(id, n)
 WHERE d.id = v.id;

-- ─── 3. Retitle the six offices ────────────────────────────────────────────────────────────
UPDATE essentials.offices o SET title = v.title, normalized_position_name = v.title
  FROM (VALUES
    ('8391fb00-171a-4984-8bc7-2d080fc03a24'::uuid, 'Council Member (District 1)'),
    ('95879f8c-5cd2-4042-86eb-b11c14fea767'::uuid, 'Council Member (District 2)'),
    ('0542b22b-61e1-4a3d-be3c-104a33252d21'::uuid, 'Council Member (District 3)'),
    ('143f683f-96a8-4924-92fa-fbc6bc3444e9'::uuid, 'Council Member (District 4)'),
    ('220e2cb5-f268-423a-b9a8-2f187f94d9b5'::uuid, 'Council Member (District 5)'),
    ('7f596dd4-1480-408f-bef8-b7b951b57142'::uuid, 'Council Member (District 6)')
  ) AS v(id, title)
 WHERE o.id = v.id;

-- ─── 4. POST-VERIFY ────────────────────────────────────────────────────────────────────────
DO $$
DECLARE bad int; v_txt text;
BEGIN
  -- six polygons, none overlapping another
  SELECT count(*) INTO bad FROM essentials.geofence_boundaries
   WHERE geo_id LIKE 'torrance-council-district-%' AND mtfcc = 'X0001';
  IF bad <> 6 THEN RAISE EXCEPTION 'CA_0329: % Torrance district polygons, expected 6', bad; END IF;
  SELECT count(*) INTO bad
    FROM essentials.geofence_boundaries a JOIN essentials.geofence_boundaries b
      ON a.geo_id < b.geo_id AND a.mtfcc = 'X0001' AND b.mtfcc = 'X0001'
   WHERE a.geo_id LIKE 'torrance-council-district-%' AND b.geo_id LIKE 'torrance-council-district-%'
     AND public.ST_Area(public.ST_Intersection(a.geometry, b.geometry)) > 1e-7;   -- ~1,000 m2 (planar degrees; no ::geography, decision 0006)
  IF bad <> 0 THEN RAISE EXCEPTION 'CA_0329: % pair(s) of Torrance districts overlap', bad; END IF;

  -- each polygon lies inside the city (TIGER place, which also takes in ocean)
  SELECT count(*) INTO bad
    FROM essentials.geofence_boundaries b
    JOIN essentials.geofence_boundaries t ON t.geo_id = '0680000' AND t.mtfcc = 'G4110'
   WHERE b.geo_id LIKE 'torrance-council-district-%' AND b.mtfcc = 'X0001'
     AND public.ST_Area(public.ST_Intersection(b.geometry, t.geometry)) / public.ST_Area(b.geometry) < 0.995;
  IF bad <> 0 THEN RAISE EXCEPTION 'CA_0329: % Torrance district(s) spill outside the city', bad; END IF;

  -- END TO END: an interior point of district N reaches exactly one council member, the right one,
  -- plus the Mayor
  SELECT string_agg(v.n || ':' || coalesce(x.names, 'NONE'), '; ') INTO v_txt
    FROM (VALUES (1, 'David Kartsonis'), (2, 'Bridgett Lewis'), (3, 'Asam Sheikh'),
                 (4, 'Linda Barnett'), (5, 'Betty Lieu'), (6, 'Jeremy Gerson')) AS v(n, expected)
    JOIN essentials.geofence_boundaries pt ON pt.geo_id = 'torrance-council-district-' || v.n AND pt.mtfcc = 'X0001'
    LEFT JOIN LATERAL (
      SELECT string_agg(p.full_name, ',' ORDER BY p.full_name) AS names
        FROM essentials.geofence_boundaries gb
        JOIN essentials.districts d ON d.geo_id = gb.geo_id AND d.mtfcc = gb.mtfcc
        JOIN essentials.offices o ON o.district_id = d.id
        JOIN essentials.office_current_holder och ON och.office_id = o.id
        JOIN essentials.politicians p ON p.id = och.politician_id
       WHERE (gb.geo_id LIKE 'torrance-council-district-%' OR gb.geo_id = '0680000')
         AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(pt.geometry))
    ) x ON true
   WHERE x.names IS DISTINCT FROM (SELECT string_agg(n, ',' ORDER BY n) FROM unnest(ARRAY[v.expected, 'Sharon Kalani']) n);
  IF v_txt IS NOT NULL THEN RAISE EXCEPTION 'CA_0329: a district point reaches the wrong people: %', v_txt; END IF;

  -- nothing is left at large on the whole city except the Mayor
  SELECT count(*) INTO bad FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
   WHERE d.geo_id = '0680000' AND d.district_type = 'LOCAL';
  IF bad <> 0 THEN RAISE EXCEPTION 'CA_0329: % council office(s) still on the whole-city row', bad; END IF;
  SELECT count(*) INTO bad FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
   WHERE d.geo_id = '0680000' AND d.district_type = 'LOCAL_EXEC' AND o.title = 'Mayor';
  IF bad <> 1 THEN RAISE EXCEPTION 'CA_0329: expected the Mayor alone on the whole city, found %', bad; END IF;
END $$;

COMMIT;
